// ======================================================
// NORMALIZAÇÃO DAS TASKS - PLANNER
// Entrada: respostas dos vários HTTP Requests após o Merge
// Saída: 1 item por Task
// ======================================================

const PLANOS = {
  "CONFIGURE_ID_020": "Governança",
  "CONFIGURE_ID_021": "Operações"
};

const BUCKETS = {

  // GOVERNANÇA
  "CONFIGURE_ID_022": "Concluídas",
  "CONFIGURE_ID_016": "Pausadas",
  "CONFIGURE_ID_014": "Treinamento da Equipe",
  "CONFIGURE_ID_012": "Aguardando Retorno",
  "CONFIGURE_ID_010": "Iniciadas",
  "CONFIGURE_ID_023": "Priorizado - Não iniciado",
  "CONFIGURE_ID_024": "Mapeados",

  // OPERAÇÕES
  "CONFIGURE_ID_004": "Pausadas",
  "CONFIGURE_ID_006": "Aguardando Retorno",
  "CONFIGURE_ID_025": "Concluídas",
  "CONFIGURE_ID_008": "Em andamento",
  "CONFIGURE_ID_026": "Não iniciadas"
};

const resultado = [];

for (const item of items) {

  // Cada HTTP Request entrega as tasks dentro de value[]
  const tasks = item.json.value ?? [];

  for (const task of tasks) {

    resultado.push({
      json: {

        // Identificação
        id: task.id,
        planId: task.planId,
        bucketId: task.bucketId,

        // Identificação amigável
        board: PLANOS[task.planId] ?? "Desconhecido",
        bucket: BUCKETS[task.bucketId] ?? "Desconhecido",

        // Dados da atividade
        title: task.title,
        orderHint: task.orderHint,
        assigneePriority: task.assigneePriority,

        // Progresso
        percentComplete: task.percentComplete,

        // Datas
        startDateTime: task.startDateTime,
        createdDateTime: task.createdDateTime,
        dueDateTime: task.dueDateTime

      }
    });
  }
}

return resultado;

// ======================================================
// CONSOLIDAR TASK + DETAILS + CHECKLIST
// ======================================================

// Details retornados pelo HTTP atual
const detailsItems = $input.all();

// Tasks originais normalizadas
const tasksOriginais = $('Normalizar Tasks').all();

// Cria índice por ID para cruzamento rápido
const tasksPorId = new Map(
  tasksOriginais.map(item => [
    item.json.id,
    item.json
  ])
);

return detailsItems.map(item => {

  const details = item.json;

  // Localiza a task original pelo mesmo ID
  const task = tasksPorId.get(details.id);

  if (!task) {
    throw new Error(
      `Task original não encontrada para o ID: ${details.id}`
    );
  }

  // Transforma checklist em array
  const checklist = Object.values(details.checklist ?? {})
    .map(check => ({
      title: check.title ?? "",
      isChecked: check.isChecked
        ? "Concluído"
        : "Não concluído"
    }));

  // Contadores
  const checklistTotal = checklist.length;

  const checklistConcluido = checklist.filter(
    check => check.isChecked === "Concluído"
  ).length;

  const checklistPendente =
    checklistTotal - checklistConcluido;

  // Resultado consolidado
  return {
    json: {
      ...task,

      // Converte percentual para status
      percentComplete:
        task.percentComplete === 0
          ? "Não iniciado"
          : task.percentComplete === 50
            ? "Em andamento"
            : task.percentComplete === 100
              ? "Concluída"
              : "Não identificado",

      description: details.description ?? "",

      checklistTotal,
      checklistConcluido,
      checklistPendente,

      checklist
    }
  };

});

// ======================================================
// CONSOLIDAÇÃO FINAL
// 1 ITEM COM TODAS AS ATIVIDADES
// ======================================================

// Tasks já consolidadas
const tasks = $('Normalizar Detalhes').all();

// Respostas do Obter Mensagens
const respostas = $input.all();

// --------------------------------------
// LIMPA HTML
// --------------------------------------
function limparHtml(html = '') {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&quot;/gi, '"')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\r/g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// --------------------------------------
// INDEXA MENSAGENS POR TASK
// --------------------------------------
const mensagensPorTask = new Map();

for (const item of respostas) {

  const json = item.json ?? {};

  if (!Array.isArray(json.value)) continue;

  for (const msg of json.value) {

    const taskId = msg.parentEntityId;

    if (!taskId || msg.deletedDateTime) continue;

    const mensagem = limparHtml(msg.content ?? '');

    if (!mensagem) continue;

    if (!mensagensPorTask.has(taskId)) {
      mensagensPorTask.set(taskId, []);
    }

    mensagensPorTask.get(taskId).push({
      data: msg.createdDateTime,
      mensagem
    });
  }
}

// --------------------------------------
// CONSOLIDA AS ATIVIDADES
// --------------------------------------
const atividades = tasks.map(item => {

  const task = item.json;

  let comentarios =
    mensagensPorTask.get(task.id) ?? [];

  comentarios.sort(
    (a, b) =>
      new Date(b.data) - new Date(a.data)
  );

  // Somente os 3 comentários mais recentes
  comentarios = comentarios.slice(0, 3);

  // Ex.: 0/8, 2/4, 3/12
  const progressoChecklist =
    `${task.checklistConcluido ?? 0}/${task.checklistTotal ?? 0}`;

  return {
    ...task,

    progressoChecklist,

    comentariosTotal: comentarios.length,
    comentarios
  };
});

// --------------------------------------
// SOMENTE 1 ITEM DE SAÍDA
// --------------------------------------
return [
  {
    json: {
      totalAtividades: atividades.length,
      atividades
    }
  }
];

// ======================================================
// RESUMO DE CONTAGENS
// ======================================================

const tasks = $input.all().flatMap(item => item.json.value ?? []);

// Data atual - horário de Brasília
const agora = new Date(
  new Date().toLocaleString('en-US', {
    timeZone: 'America/Sao_Paulo'
  })
);

// ------------------------------------------------------
// MÊS ATUAL
// ------------------------------------------------------

const inicioMes = new Date(
  agora.getFullYear(),
  agora.getMonth(),
  1
);

const inicioProximoMes = new Date(
  agora.getFullYear(),
  agora.getMonth() + 1,
  1
);

// ------------------------------------------------------
// SEMANA ANTERIOR COMPLETA
// Segunda 00:00 até segunda seguinte 00:00
// Horário de Brasília (UTC-03:00)
// ------------------------------------------------------

const agoraBR = new Date(
  new Date().toLocaleString('en-US', {
    timeZone: 'America/Sao_Paulo'
  })
);

const hojeBR = new Date(
  agoraBR.getFullYear(),
  agoraBR.getMonth(),
  agoraBR.getDate()
);

const diaSemana = hojeBR.getDay();

const diasDesdeSegunda =
  diaSemana === 0 ? 6 : diaSemana - 1;

const segundaAtual = new Date(hojeBR);
segundaAtual.setDate(
  hojeBR.getDate() - diasDesdeSegunda
);

const segundaAnterior = new Date(segundaAtual);
segundaAnterior.setDate(
  segundaAtual.getDate() - 7
);

// Converte os limites de Brasília para UTC
const inicioSemanaAnterior = new Date(
  segundaAnterior.getTime() + (3 * 60 * 60 * 1000)
);

const inicioSemanaAtual = new Date(
  segundaAtual.getTime() + (3 * 60 * 60 * 1000)
);

// ------------------------------------------------------
// CONTAGENS
// ------------------------------------------------------

const concluidasMes = tasks.filter(task => {

  if (!task.completedDateTime) return false;

  const data = new Date(task.completedDateTime);

  return (
    data >= inicioMes &&
    data < inicioProximoMes
  );

}).length;


const concluidasSemanaAnterior = tasks.filter(task => {

  if (!task.completedDateTime) return false;

  const data = new Date(task.completedDateTime);

  return (
    data >= inicioSemanaAnterior &&
    data < inicioSemanaAtual
  );

}).length;


// Não iniciadas
// Funciona tanto com Graph bruto (0)
// quanto com sua normalização ("Não iniciado")

const naoIniciadas = tasks.filter(task =>
  task.percentComplete === 0 ||
  task.percentComplete === "Não iniciado"
).length;


// ------------------------------------------------------
// SAÍDA
// ------------------------------------------------------

return [{
  json: {
    concluidas_mes: concluidasMes,
    concluidas_semana_anterior: concluidasSemanaAnterior,
    nao_iniciadas: naoIniciadas
  }
}];

// ======================================================
// INDICADORES SEMANAIS + RESUMO DAS ATIVIDADES
// Timezone: America/Sao_Paulo
// ======================================================

// 1. BUSCAR TODAS AS TAREFAS
// Fonte original, antes do filtro para comentários.

const FONTES = [
  "Merge - Todos os Projetos",
  "Merge - Todos os Projetos1"
];

function lerNode(nome) {
  try {
    return $(nome).all().map(i => i.json);
  } catch (e) {
    return [];
  }
}

function extrairTarefas(itens) {
  return itens.flatMap(j => {
    if (Array.isArray(j.value)) {
      return j.value.filter(t => t.id && t.bucketId);
    }
    if (j.id && j.bucketId) return [j];
    return [];
  });
}

let raw = [];

for (const nome of FONTES) {
  raw = extrairTarefas(lerNode(nome));
  if (raw.length) break;
}

// Permite executar também quando as tarefas
// estiverem diretamente na entrada.
if (!raw.length) {
  raw = extrairTarefas($input.all().map(i => i.json));
}

if (!raw.length) {
  throw new Error(
    "Fonte de tarefas não encontrada. " +
    "Configure FONTES com o nome do node " +
    "que reúne os 12 buckets do Planner."
  );
}

// Remover duplicidades
const tasks = [
  ...new Map(raw.map(t => [t.id, t])).values()
];

// 2. MAPA DOS BUCKETS

const B = {
  "CONFIGURE_ID_025":
    ["Operações", "Concluídas"],
  "CONFIGURE_ID_008":
    ["Operações", "Em andamento"],
  "CONFIGURE_ID_006":
    ["Operações", "Aguardando Retorno"],
  "CONFIGURE_ID_004":
    ["Operações", "Pausadas"],
  "CONFIGURE_ID_026":
    ["Operações", "Não iniciadas"],

  "CONFIGURE_ID_022":
    ["Governança", "Concluídas"],
  "CONFIGURE_ID_010":
    ["Governança", "Iniciadas"],
  "CONFIGURE_ID_012":
    ["Governança", "Aguardando Retorno"],
  "CONFIGURE_ID_016":
    ["Governança", "Pausadas"],
  "CONFIGURE_ID_023":
    ["Governança", "Priorizado - Não iniciado"],
  "CONFIGURE_ID_024":
    ["Governança", "Mapeados"],
  "CONFIGURE_ID_014":
    ["Governança", "Treinamento da Equipe"]
};

const meta = t =>
  B[t.bucketId] ?? ["Desconhecido", "Desconhecido"];

// 3. DATAS

function ymdBR(valor = new Date()) {
  if (!valor) return null;

  const partes = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(new Date(valor));

  const p = Object.fromEntries(
    partes.map(x => [x.type, x.value])
  );

  return `${p.year}-${p.month}-${p.day}`;
}

function addDays(data, dias) {
  const d = new Date(`${data}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() + dias);
  return d.toISOString().slice(0, 10);
}

const hoje = ymdBR();
const inicioAtual = addDays(hoje, -6);
const fimAtual = hoje;

const inicioAnterior = addDays(hoje, -13);
const fimAnterior = addDays(hoje, -7);

const inicioMesAtual = `${hoje.slice(0, 7)}-01`;
const inicioMesAnterior =
  addDays(inicioMesAtual, -1).slice(0, 7) + "-01";

function noPeriodo(data, inicio, fim) {
  if (!data) return false;
  const d = ymdBR(data);
  return d >= inicio && d <= fim;
}

function contarStatus(statuses) {
  return tasks.filter(t =>
    statuses.includes(meta(t)[1])
  ).length;
}

// 4. INDICADORES

const concluidas = tasks.filter(t =>
  meta(t)[1] === "Concluídas"
);

const recebidasAtual = tasks.filter(t =>
  noPeriodo(t.createdDateTime, inicioAtual, fimAtual)
);

const recebidasAnterior = tasks.filter(t =>
  noPeriodo(t.createdDateTime, inicioAnterior, fimAnterior)
);

const concluidasAtual = concluidas.filter(t =>
  noPeriodo(t.completedDateTime, inicioAtual, fimAtual)
);

const concluidasAnterior = concluidas.filter(t =>
  noPeriodo(t.completedDateTime, inicioAnterior, fimAnterior)
);

const emAndamento = contarStatus([
  "Em andamento",
  "Iniciadas"
]);

const aguardandoRetorno = contarStatus([
  "Aguardando Retorno"
]);

const pausadas = contarStatus(["Pausadas"]);

const naoIniciadas = contarStatus([
  "Não iniciadas",
  "Priorizado - Não iniciado",
  "Mapeados"
]);

const mesAtual = tasks.filter(t =>
  noPeriodo(t.createdDateTime, inicioMesAtual, hoje)
).length;

const mesAnterior = tasks.filter(t =>
  noPeriodo(
    t.createdDateTime,
    inicioMesAnterior,
    addDays(inicioMesAtual, -1)
  )
).length;

// 5. COMENTÁRIOS
// Mensagens vinculadas por parentEntityId.

const mensagensPorTask = new Map();

const respostas = lerNode("Obter Mensagens1");

for (const resposta of respostas) {
  const mensagens = Array.isArray(resposta.value)
    ? resposta.value
    : resposta.parentEntityId
      ? [resposta]
      : [];

  for (const m of mensagens) {
    if (!m.parentEntityId || m.deletedDateTime) continue;

    // Somente comentários da semana atual
    if (!noPeriodo(
      m.createdDateTime,
      inicioAtual,
      fimAtual
    )) continue;

    const id = m.parentEntityId;
    const lista = mensagensPorTask.get(id) ?? [];

    lista.push(m);
    mensagensPorTask.set(id, lista);
  }
}

function limparTexto(valor) {
  return String(valor ?? "")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizarAtividade(t) {
  const [board, status] = meta(t);

  const comentarios = (mensagensPorTask.get(t.id) ?? [])
    .sort((a, b) =>
      new Date(b.createdDateTime) -
      new Date(a.createdDateTime)
    )
    .slice(0, 3)
    .map(m => ({
      data: m.createdDateTime,
      texto: limparTexto(
        m.body?.content ?? m.content
      ).slice(0, 1200)
    }))
    .filter(m => m.texto);

  return {
    id: t.id,
    titulo: t.title ?? "",
    board,
    status,
    percentual: t.percentComplete ?? null,
    comentarios
  };
}

// 6. ATIVIDADES RELEVANTES

const statusAtivos = [
  "Em andamento",
  "Iniciadas",
  "Aguardando Retorno"
];

const acompanhamento = tasks
  .filter(t => statusAtivos.includes(meta(t)[1]))
  .map(normalizarAtividade);

const entregasSemana = concluidasAtual
  .map(normalizarAtividade);

// 7. SAÍDA PARA A IA

return [{
  json: {
    periodo: {
      referencia: hoje,
      ultimos_7_dias: {
        inicio: inicioAtual,
        fim: fimAtual
      },
      periodo_anterior: {
        inicio: inicioAnterior,
        fim: fimAnterior
      },
      mes_atual: inicioMesAtual.slice(0, 7),
      mes_anterior: inicioMesAnterior.slice(0, 7)
    },

    indicadores: {
      solicitacoes_ultimos_7_dias: recebidasAtual.length,
      entregues_ultimos_7_dias: concluidasAtual.length,

      solicitacoes_7_dias_anteriores: recebidasAnterior.length,
      entregues_7_dias_anteriores: concluidasAnterior.length,

      em_andamento: emAndamento,
      aguardando_retorno: aguardandoRetorno,
      em_curso: emAndamento + aguardandoRetorno,
      pausadas,
      nao_iniciadas: naoIniciadas,

      solicitacoes_mes_atual: mesAtual,
      solicitacoes_mes_anterior: mesAnterior
    },

    atividades: {
      em_acompanhamento: acompanhamento,
      concluidas_semana: entregasSemana
    }
  }
}];

const raw = $input.all().flatMap(i =>
  Array.isArray(i.json.value) ? i.json.value :
  i.json.id ? [i.json] : []
);

const tasks = [...new Map(
  raw.filter(t => t.id).map(t => [t.id, t])
).values()];

const B = {
  "CONFIGURE_ID_025": ["Operações","Concluídas"],
  "CONFIGURE_ID_008": ["Operações","Em andamento"],
  "CONFIGURE_ID_006": ["Operações","Aguardando Retorno"],
  "CONFIGURE_ID_004": ["Operações","Pausadas"],
  "CONFIGURE_ID_026": ["Operações","Não iniciadas"],
  "CONFIGURE_ID_022": ["Governança","Concluídas"],
  "CONFIGURE_ID_010": ["Governança","Iniciadas"],
  "CONFIGURE_ID_012": ["Governança","Aguardando Retorno"],
  "CONFIGURE_ID_016": ["Governança","Pausadas"],
  "CONFIGURE_ID_023": ["Governança","Priorizado - Não iniciado"],
  "CONFIGURE_ID_024": ["Governança","Mapeados"],
  "CONFIGURE_ID_014": ["Governança","Treinamento da Equipe"]
};

function ymdBR(date) {
  const p = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(new Date(date));

  const o = Object.fromEntries(p.map(x => [x.type,x.value]));
  return `${o.year}-${o.month}-${o.day}`;
}

function addDays(s,n) {
  const d = new Date(`${s}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate()+n);
  return d.toISOString().slice(0,10);
}

const fim = ymdBR(new Date());
const inicio = addDays(fim,-6);

const dentro = date =>
  date && ymdBR(date) >= inicio && ymdBR(date) <= fim;

const acompanhamento = [
  "Em andamento","Iniciadas","Aguardando Retorno"
];

return tasks.flatMap(t => {
  const [board,bucket] = B[t.bucketId] ?? ["Desconhecido","Desconhecido"];

  const criada = dentro(t.createdDateTime);
  const concluida = bucket === "Concluídas" &&
    dentro(t.completedDateTime);
  const ativa = acompanhamento.includes(bucket);

  if (!criada && !concluida && !ativa) return [];

  return [{
    json: {
      id: t.id,
      planId: t.planId,
      bucketId: t.bucketId,
      board,
      bucket,
      title: t.title,
      percentComplete: t.percentComplete,
      createdDateTime: t.createdDateTime,
      completedDateTime: t.completedDateTime ?? null,
      semana: {inicio,fim},
      referencia: {
        criada_na_semana: Boolean(criada),
        concluida_na_semana: Boolean(concluida),
        em_acompanhamento: ativa
      }
    }
  }];
});

// ======================================================
// FORMATAR HTML SEGUNDA — MICROSOFT TEAMS
// Cabeçalho executivo + panorama + detalhamento original
// Run Once for All Items
// ======================================================

// 1. DADOS CONSOLIDADOS
const origem = $("conclusão das informações").first().json;

const atividades = Array.isArray(origem.atividades)
  ? origem.atividades
  : [];

const normalizar = v =>
  String(v ?? "").trim().toLowerCase();

const emCursoBuckets = [
  "em andamento",
  "iniciadas",
  "aguardando retorno"
];

const emCurso = atividades.filter(a =>
  emCursoBuckets.includes(normalizar(a.bucket))
).length;

const pausadas = atividades.filter(a =>
  normalizar(a.bucket) === "pausadas"
).length;

const total = Number(origem.totalAtividades ?? atividades.length);
const concluidasMes = Number(origem.concluidas_mes ?? 0);
const concluidasSemana = Number(origem.concluidas_semana_anterior ?? 0);
const naoIniciadas = Number(origem.nao_iniciadas ?? 0);

const numero = v =>
  Number(v).toLocaleString("pt-BR");

// 2. SAÍDA DO GEMINI
const resposta = $input.first().json;

function obterTexto(obj) {
  let valor = obj.output ?? obj.text ?? obj.response ?? obj;

  if (typeof valor === "object" && valor !== null) {
    valor = valor.output ??
            valor.text ??
            valor.html ??
            JSON.stringify(valor);
  }

  return String(valor ?? "")
    .trim()
    .replace(/^```(?:html)?\s*/i, "")
    .replace(/\s*```$/i, "");
}

const textoGemini = obterTexto(resposta);

// 3. EXTRAIR BLOCOS
function extrairEntre(texto, inicio, fim) {
  const posInicio = texto.indexOf(inicio);
  const posFim = texto.indexOf(fim);

  if (posInicio < 0 || posFim < 0 || posFim <= posInicio) {
    return "";
  }

  return texto
    .slice(posInicio + inicio.length, posFim)
    .trim();
}

const panorama = extrairEntre(
  textoGemini,
  "<!-- PANORAMA_INICIO -->",
  "<!-- PANORAMA_FIM -->"
);

const marcadorAtividades = "<!-- ATIVIDADES_INICIO -->";

let detalhamento = "";

if (textoGemini.includes(marcadorAtividades)) {
  detalhamento = textoGemini
    .split(marcadorAtividades)
    .slice(1)
    .join(marcadorAtividades)
    .trim();
} else {
  // Compatibilidade com saída antiga do Gemini
  const match = textoGemini.match(
    /<h2[^>]*>\s*(?:🏛️\s*)?Atividades de Governança/i
  );

  if (match) {
    detalhamento = textoGemini
      .slice(match.index)
      .trim();
  }
}

// 4. VALIDAR CONTEÚDO
if (!panorama) {
  throw new Error(
    "Gemini não retornou o bloco PANORAMA. Verifique o prompt."
  );
}

if (!detalhamento) {
  throw new Error(
    "Gemini não retornou o detalhamento das atividades."
  );
}

// 5. FORMATAÇÃO DO CABEÇALHO
const celula = (valor, titulo) => `
<td align="center">
  <h2>${numero(valor)}</h2>
  <small>${titulo}</small>
</td>`;

const html = `
<div>

  <p>
    <small>
      <strong>OPERAÇÕES E GOVERNANÇA | ACOMPANHAMENTO SEMANAL</strong>
    </small>
  </p>

  <h2>📊 Acompanhamento semanal de atividades</h2>

  <p>
    Visão consolidada dos projetos em execução,
    pendências e principais atualizações.
  </p>

  <hr>

